package main

import (
	"encoding/json"
	"net/http"
	"strconv"
	"time"
)

type putRequest struct {
	Value      string `json:"value"`
	TTLSeconds int    `json:"ttl_seconds"`
}

type getResponse struct {
	Key   string `json:"key"`
	Value string `json:"value"`
}

type errorResponse struct {
	Error string `json:"error"`
}

func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	json.NewEncoder(w).Encode(v)
}

func writeError(w http.ResponseWriter, status int, msg string) {
	writeJSON(w, status, errorResponse{Error: msg})
}

var store *Store

func registerRoutes(mux *http.ServeMux) {
	store = NewStore()

	mux.HandleFunc("PUT /cache/{key}", handlePut)
	mux.HandleFunc("GET /cache/{key}", handleGet)
	mux.HandleFunc("DELETE /cache/{key}", handleDelete)
}

func handlePut(w http.ResponseWriter, r *http.Request) {
	key := r.PathValue("key")
	if key == "" {
		writeError(w, http.StatusBadRequest, "key is required")
		return
	}

	var req putRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeError(w, http.StatusBadRequest, "malformed JSON")
		return
	}

	if req.Value == "" {
		writeError(w, http.StatusBadRequest, "value is required")
		return
	}

	if req.TTLSeconds <= 0 {
		writeError(w, http.StatusBadRequest, "ttl_seconds must be > 0")
		return
	}

	store.Put(key, req.Value, time.Duration(req.TTLSeconds)*time.Second)
	writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
}

func handleGet(w http.ResponseWriter, r *http.Request) {
	key := r.PathValue("key")
	if key == "" {
		writeError(w, http.StatusBadRequest, "key is required")
		return
	}

	value, ok := store.Get(key)
	if !ok {
		cacheMissesTotal.Inc()
		writeError(w, http.StatusNotFound, "key not found")
		return
	}

	cacheHitsTotal.Inc()
	writeJSON(w, http.StatusOK, getResponse{Key: key, Value: value})
}

func handleDelete(w http.ResponseWriter, r *http.Request) {
	key := r.PathValue("key")
	if key == "" {
		writeError(w, http.StatusBadRequest, "key is required")
		return
	}

	if store.Delete(key) {
		w.WriteHeader(http.StatusOK)
		json.NewEncoder(w).Encode(map[string]string{"status": "deleted"})
	} else {
		writeError(w, http.StatusNotFound, "key not found")
	}
}
